// uart_monitor.sv - generated by uvm_full_tb_generator.py, filled in with UART protocol logic
//   Decodes 8N1 frames on both lines (uart_tx_o: SoC->PC, uart_rx_i: PC->SoC),
//   sampling in the middle of each bit; one item per byte on the analysis port.
class uart_monitor extends uvm_monitor;
virtual uart_if vif;
uvm_analysis_port #(uart_item) ap;
int unsigned clks_per_bit = 64;
`uvm_component_utils(uart_monitor)
function new(string n,uvm_component p); super.new(n,p); ap=new("ap",this); endfunction

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db#(virtual uart_if)::get(this, "", "uart_vif", vif))
    `uvm_fatal("NOVIF", "uart_vif not set in uvm_config_db")
  void'(uvm_config_db#(int unsigned)::get(this, "", "uart_clks_per_bit", clks_per_bit));
endfunction

task run_phase(uvm_phase phase);
  wait (vif.rst_n === 1'b1);
  fork
    watch_line(UART_SOC_TO_PC);
    watch_line(UART_PC_TO_SOC);
  join
endtask

function bit line(uart_dir_e d);
  return (d == UART_SOC_TO_PC) ? vif.uart_tx_o : vif.uart_rx_i;
endfunction

task automatic watch_line(uart_dir_e d);
  bit prev = 1'b1;
  forever begin
    @(posedge vif.clk);
    if (prev === 1'b1 && line(d) === 1'b0) begin      // start bit
      uart_item tr = uart_item::type_id::create("tr");
      tr.dir = d;
      repeat (clks_per_bit / 2) @(posedge vif.clk);
      if (line(d) !== 1'b0) begin prev = line(d); continue; end   // glitch
      for (int i = 0; i < 8; i++) begin
        repeat (clks_per_bit) @(posedge vif.clk);
        tr.data[i] = line(d);
      end
      repeat (clks_per_bit) @(posedge vif.clk);       // middle of stop bit
      tr.framing_err = (line(d) !== 1'b1);
      if (tr.framing_err) `uvm_error("UART_MON", {"framing error: ", tr.convert2string()})
      `uvm_info("UART_MON", tr.convert2string(), UVM_HIGH)
      ap.write(tr);
    end
    prev = line(d);
  end
endtask
endclass
